import r from"./BaseSegment.js";import{Vec3 as s}from"../../math/Vec3.js";import{lerp as p}from"../../math/functions/Vec3Func.js";const h=new s;class o extends r{constructor(e,t,i=0,n=0){super(),this.p0=e,this.p1=t,this.tiltStart=i,this.tiltEnd=n,this._len=-1}updateLength(){this._len=h.sub(this.p1,this.p0).len()}getPointAt(e,t=new s){return p(t,this.p0,this.p1,e),t}getTangentAt(e,t=new s){return t.sub(this.p1,this.p0).normalize()}lastPoint(){return this.p1}}export{o as default};
